/* ==========================================================================
   Service Desk theme
   Navy  #042471 — structure (sidebar, headers, deep accents)
   Blue  #042471 — primary actions, links, progress
   Orange #fe6100 — the one loud colour: attention / things waiting on you
   Load this AFTER appstack's app.css in _Layout.cshtml:
   <link rel="stylesheet" href="~/Content/dashboard-theme.css" />
   ========================================================================== */

:root {
    --brand-navy: #042471;
    --brand-blue: #042471;
    --brand-orange: #fe6100;
    --brand-navy-rgb: 4, 36, 113;
    --brand-blue-rgb: 4, 77, 242;
    --brand-orange-rgb: 254, 97, 0;
    /* tints used for icon chips and soft fills */
    --tint-navy: rgba(4, 36, 113, .50);
    --tint-blue: rgba(4, 77, 242, .50);
    --tint-orange: rgba(254, 97, 0, .52);
    /* Bootstrap 5 overrides */
    --bs-primary: #042471;
    --bs-primary-rgb: 4, 77, 242;
    --bs-link-color: #042471;
    --bs-link-hover-color: #042471;
    --bs-body-color: #1b2334;
}

/* --------------------------------------------------------------------------
   Bootstrap utility remap so existing bg- and text- classes pick up the brand
   -------------------------------------------------------------------------- */
.bg-primary {
    background-color: var(--brand-blue) !important;
}

.bg-dark {
    background-color: var(--brand-navy) !important;
}

.bg-warning {
    background-color: var(--brand-orange) !important;
    color: #fff !important;
}

.text-primary {
    color: var(--brand-blue) !important;
}

.btn-primary {
    --bs-btn-bg: var(--brand-blue);
    --bs-btn-border-color: var(--brand-blue);
    --bs-btn-hover-bg: #0340c9;
    --bs-btn-hover-border-color: #0340c9;
    --bs-btn-active-bg: var(--brand-navy);
    --bs-btn-active-border-color: var(--brand-navy);
    --bs-btn-focus-shadow-rgb: var(--brand-blue-rgb);
}

.btn-outline-primary {
    --bs-btn-color: var(--brand-blue);
    --bs-btn-border-color: var(--brand-blue);
    --bs-btn-hover-bg: var(--brand-blue);
    --bs-btn-hover-border-color: var(--brand-blue);
}

.btn-secondary {
    --bs-btn-bg: #eef1f7;
    --bs-btn-border-color: #dde3ee;
    --bs-btn-color: var(--brand-navy);
    --bs-btn-hover-bg: #dde3ee;
    --bs-btn-hover-border-color: #ccd5e6;
    --bs-btn-hover-color: var(--brand-navy);
}

a {
    color: var(--brand-blue);
}

    a:hover {
        color: var(--brand-navy);
    }

.form-control:focus, .form-select:focus {
    border-color: var(--brand-blue);
    box-shadow: 0 0 0 .2rem rgba(var(--brand-blue-rgb), .15);
}

/* --------------------------------------------------------------------------
   Page header
   -------------------------------------------------------------------------- */
h3.mb-0 {
    color: var(--brand-navy);
    font-weight: 600;
    letter-spacing: -.01em;
}

.page-rule {
    height: 3px;
    width: 56px;
    margin-top: .6rem;
    background: linear-gradient(90deg, var(--brand-orange) 0 60%, var(--brand-blue) 60% 100%);
    border-radius: 2px;
}

/* --------------------------------------------------------------------------
   Cards: a coloured top edge carries the meaning, everything else stays quiet
   -------------------------------------------------------------------------- */
.card {
    border: 1px solid #e7ebf3;
    box-shadow: 0 1px 2px rgba(var(--brand-navy-rgb), .05);
}

.accent-card {
    position: relative;
    overflow: hidden;
}



    .accent-card .h1 {
        color: var(--brand-navy);
        font-weight: 600;
    }

    .accent-card .card-title {
        color: #55607a;
        font-weight: 500;
    }

    .accent-card a {
        color: var(--accent, var(--brand-blue));
        font-weight: 500;
    }

        .accent-card a:hover {
            color: var(--brand-navy);
        }

/* accent variants */
.accent-orange {
    --accent: var(--brand-orange);
    --accent-tint: var(--tint-orange);
}

.accent-blue {
    --accent: var(--brand-blue);
    --accent-tint: var(--tint-blue);
}

.accent-navy {
    --accent: var(--brand-navy);
    --accent-tint: var(--tint-navy);
}

.accent-blue-light {
    --accent: #3d7bf7;
    --accent-tint: rgba(61, 123, 247, .52);
}

.accent-orange-light {
    --accent: #ff8a3d;
    --accent-tint: rgba(255, 138, 61, .54);
}

/* the little square icon chip appstack calls .stat */
.accent-card .stat,
.stat-brand {
    background: var(--accent-tint, var(--tint-blue));
    color: var(--accent, var(--brand-blue));
    border-radius: .5rem;
}

    .accent-card .stat svg,
    .stat-brand svg {
        color: inherit;
        stroke: currentColor;
    }

/* --------------------------------------------------------------------------
   Category tiles — navy chip, blue count, orange edge on hover
   -------------------------------------------------------------------------- */
.category-card {
    border-left: 3px solid transparent;
    transition: border-color .15s ease;
}

    .category-card:hover {
        border-left-color: var(--brand-orange);
    }

    .category-card .stat {
        background: var(--tint-navy);
        color: var(--brand-navy);
        border-radius: .5rem;
    }

    .category-card .card-title {
        color: var(--brand-navy);
    }

    .category-card .h4 {
        color: var(--brand-blue);
        font-weight: 600;
    }

/* --------------------------------------------------------------------------
   Team progress bars
   -------------------------------------------------------------------------- */
.team-row .progress {
    background-color: #edf0f7;
    border-radius: 3px;
}

.team-row .progress-bar {
    background: linear-gradient(90deg, var(--brand-blue), #3d7bf7);
    border-radius: 3px;
}

/* every third team gets the orange bar so the list stays readable at a glance */
.team-row.team-alt .progress-bar {
    background: linear-gradient(90deg, var(--brand-orange), #ff9a52);
}

.team-row .team-name {
    color: var(--brand-navy);
    font-weight: 500;
}

.team-row strong {
    color: var(--brand-blue);
}

.team-row.team-alt strong {
    color: var(--brand-orange);
}

/* --------------------------------------------------------------------------
   Quick actions — navy panels, orange icon chip
   -------------------------------------------------------------------------- */
.quick-action .card-body {
    padding-block: 1.5rem;
}

.quick-action.card {
    background: var(--brand-navy);
    border-color: var(--brand-navy);
    color: #fff;
    transition: background-color .15s ease;
}

    .quick-action.card:hover {
        background: #063099;
    }

.quick-action h5 {
    color: #fff;
    font-weight: 500;
}

.quick-action .stat {
    background: rgba(254, 97, 0, .18);
    color: var(--brand-orange);
    border-radius: .6rem;
    width: 44px;
    height: 44px;
    display: flex;
    align-items: center;
    justify-content: center;
}

/* --------------------------------------------------------------------------
   Modals
   -------------------------------------------------------------------------- */
.modal-header {
    background: var(--brand-navy);
    color: #fff;
    border-bottom: 3px solid var(--brand-orange);
}

    .modal-header .modal-title {
        color: #fff;
        font-weight: 500;
    }

    .modal-header .btn-close {
        filter: invert(1) grayscale(100%) brightness(200%);
    }

.modal-body table thead th {
    color: var(--brand-navy);
    border-bottom: 2px solid #e7ebf3;
    font-weight: 600;
}

.modal-body table tbody tr:hover {
    background-color: rgba(var(--brand-blue-rgb), .04);
}

.modal-body table a {
    color: var(--brand-blue);
    font-weight: 600;
}

    .modal-body table a:hover {
        color: var(--brand-orange);
    }

/* --------------------------------------------------------------------------
   Status badges — TicketService.GetTicketStatusColor() still returns bootstrap
   names, so remap the ones it uses rather than changing the C#.
   -------------------------------------------------------------------------- */
.badge.bg-secondary {
    background-color: #64748b !important;
}

.badge.bg-info {
    background-color: #3d7bf7 !important;
    color: #fff !important;
}

.badge.bg-primary {
    background-color: var(--brand-blue) !important;
}

.badge.bg-warning {
    background-color: var(--brand-orange) !important;
    color: #fff !important;
}

.badge.bg-dark {
    background-color: var(--brand-navy) !important;
}

.badge {
    font-weight: 500;
    padding: .35em .6em;
}

/* --------------------------------------------------------------------------
   Accessibility floor
   -------------------------------------------------------------------------- */
a:focus-visible, .btn:focus-visible, .card a:focus-visible {
    outline: 2px solid var(--brand-orange);
    outline-offset: 2px;
}

@media (prefers-reduced-motion: reduce) {
    * {
        transition: none !important;
    }
}



.gradient-1 {
    background: linear-gradient(135deg, #fe6100 0%, #f4385e 100%);
}

.gradient-2 {
    background: linear-gradient(135deg, #f4385e 0%, #c2428c 100%);
}

.gradient-3 {
    background: linear-gradient(135deg, #c2428c 0%, #7b5298 100%);
}

.gradient-4 {
    background: linear-gradient(135deg, #d823c8 0%, #042471 100%);
}

.gradient-5 {
    background: linear-gradient(135deg, #ca4170 0%, #81297b 100%);
}

.gradient-6 {
    background: linear-gradient(135deg, #81297b 0%, #042471 100%);
}


.gradient-1,
.gradient-2,
.gradient-3,
.gradient-4,
.gradient-5,
.gradient-6 {
    color: #fff !important;
}

.stat svg {
    color: #fff !important;
}

.card {
    margin-bottom: 10px;
}

.card-header {
    border-bottom: 2px solid #042471;
}


/* Reset cards inside accordion */
#accordion .card-header {
    border-bottom: none;
}

    #accordion .card-header .card-title {
        border-bottom: none;
    }


.callout i {
    margin-right: 10px;
}


